import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { parse } from 'lossless-json';
import * as lib from '../src/index.js';
// Copied unchanged from Neurai node daefacf, generated by independent Python struct/hashlib.
const vectors = parse(readFileSync(new URL('./fixtures/rpc5-vectors.json', import.meta.url), 'utf8'), null, (s) =>
  Number.isSafeInteger(Number(s)) ? Number(s) : BigInt(s),
);
for (const vector of vectors.cases)
  test(`independent node RPC5 vector: ${vector.name}`, () => {
    assert.equal(lib.bytesToHex(lib.depinRequestBytes(vector.method, vector.request)), vector.bytes);
    assert.equal(lib.depinRequestHash(vector.method, vector.request), vector.hash);
    assert.equal(lib.buildDepinRpcRequestPreimage(vector), vector.preimage);
  });
test('unsafe numbers, strings, floats, extra fields and old versions are rejected', () => {
  const v = vectors.cases[0];
  for (const patch of [
    { protocol: 2 },
    { timestamp_ms: 9007199254740992 },
    { timestamp_ms: '123' },
    { timestamp_ms: 1.5 },
    { extra: true },
    { args: { extra: true } },
  ])
    assert.throws(() => lib.depinRequestBytes(v.method, { ...v.request, ...patch }));
  for (const protocol of [2, 3, 4])
    assert.throws(() => lib.buildDepinRequestPreimage({ method: v.method, request: { ...v.request, protocol } }));
});
